using EqlTracker.Core;
using System.Text.Json;

internal static class PetComparisonTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool condition,string message="Pet comparison assertion failed"){if(!condition)throw new Exception(message);}
        CharacterProfile Profile(params string[] classes)=>new(){Loadouts=[new(){Name="Synthetic",Level=50,Classes=classes.ToList()}],SelectedLoadout="Synthetic"};
        PetContextCatalog Summons()=>new(){Version="fixture-v1",Spells=[new("Air","Air fixture","MAG",46,"https://example.invalid/air",1){BasePetLevel=41},new("Water","Water fixture","MAG",46,"https://example.invalid/water",1){BasePetLevel=41},new("Earth","Earth fixture","MAG",46,"https://example.invalid/earth",1){BasePetLevel=41},new("Undead","Undead fixture","NEC",46,"https://example.invalid/undead",1){BasePetLevel=39},new("Warder","Warder fixture","BST",46,"https://example.invalid/warder",1){BasePetLevel=39}]};
        ItemDefinition Item(string key,double ac=0,string[]? slots=null,string[]? classes=null)=>new(){Key=key,Name=key,Slots=slots?.ToList()??["PRIMARY","SECONDARY"],Classes=classes?.ToList()??["ALL"],Stats=slots==null || slots.Any(s=>s is "PRIMARY" or "SECONDARY" or "RANGE") ? new(){["AC"]=ac,["Damage"]=10,["Delay"]=20} : new(){["AC"]=ac},MetadataComplete=true};
        PetInventoryItem Entry(string key,int pos,string slot="Storage",int rank=0)=>new(){Id="copy:"+key+":"+pos,ItemKey=key,Name=key,Position=pos,Slot=slot,Rank=rank};
        List<PetComparisonResult> Run(CharacterProfile p,PetBuild? b=null,Catalog? c=null,PetEquipmentMode mode=PetEquipmentMode.IntendedSlots)=>PetComparisonEngine.Evaluate(p,b??new(),c??new(),Summons(),PetBuffCatalog.References(),[],mode,CancellationToken.None);
        test("Pet comparison gates summons by actual classes and level",()=>{var p=Profile("BST","NEC","WAR");Check(Run(p).Select(r=>r.Pet).Order().SequenceEqual(new[]{"Undead","Warder"}));p.ActiveLoadout.Level=0;Check(Run(p).Count==0);p.ActiveLoadout.Level=40;Check(Run(p).Count==0);});
        test("Pet comparison class aliases resolve without creating missing classes",()=>{var p=Profile("Magician","Unknown","Warrior");Check(Run(p).Count==3);p.ActiveLoadout.Classes=["Unknown"];Check(Run(p).Count==0);});
        test("Pet class and owner class access remain distinct",()=>{var p=Profile("CLR","MAG","BRD");Check(PetComparisonEngine.Access(Item("robe",classes:["CLR"]),p.ActiveLoadout,"Air")==PetClassAccess.OwnerClasses);Check(PetComparisonEngine.Access(Item("monk",classes:["MNK"]),p.ActiveLoadout,"Air")==PetClassAccess.PetClasses);Check(PetComparisonEngine.Access(Item("all"),p.ActiveLoadout,"Air")==PetClassAccess.Both);Check(PetComparisonEngine.Access(Item("rog",classes:["ROG"]),p.ActiveLoadout,"Air")==PetClassAccess.Incompatible);Check(PetComparisonEngine.Access(null,p.ActiveLoadout,"Air")==PetClassAccess.Unverified);});
        test("Intended comparison slots never silently equip storage",()=>{var p=Profile("MAG","CLR","WAR");var c=new Catalog{Items=[Item("blade")]};var b=new PetBuild{Items=[Entry("blade",1)]};var before=JsonSerializer.Serialize(b);var rows=Run(p,b,c);Check(rows.All(r=>r.Equipment.Selections.Count==0&&r.Fits[0].Reason.Contains("Stored")));Check(JsonSerializer.Serialize(b)==before);});
        test("Per-summon ranks are separate and level capped at owner",()=>{var p=Profile("MAG","WAR","CLR");var s=Summons().Spells[0];p.PetComparison.Summons[s.Id]=new(){SpellId=s.Id,Rank=10,RankConfirmed=true,LearningConfirmed=true};var rows=Run(p);Check(rows.Single(r=>r.Pet=="Air").Plan.PetLevel==50);Check(rows.Single(r=>r.Pet=="Earth").Plan.SummonRank==0);Check(rows.Single(r=>r.Pet=="Earth").Missing.Any(m=>m.Contains("rank unverified")));});
        test("Pet comparison never turns missing data into zero DPS",()=>{var rows=Run(Profile("MAG","WAR","CLR"));Check(rows.All(r=>r.Outcome==null&&r.PredictedDps=="Unavailable"&&!r.StrongTradeoff));Check(rows.Single(r=>r.Pet=="Water").FromBehind.Contains("unavailable"));Check(rows.Single(r=>r.Pet=="Air").FromBehind=="Not applicable");});
        test("Exact supported model identity and version are required",()=>{var p=Profile("MAG","WAR","CLR");var source=new PetBuild();var rows=Run(p,source);var key=rows[0].Scenario.InputKey;var model=new PetSupportedOutcome(key,PetDefinition.Version,10,2,3,1,45,4,PetEvidenceKind.Computed,"Synthetic verified model",true);var evaluated=PetComparisonEngine.Evaluate(p,source,new(),Summons(),PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,CancellationToken.None,[model]);Check(evaluated.Single(r=>r.Scenario.InputKey==key).Outcome?.Dps==16);p.PetComparison.Encounter.Seconds=60;Check(PetComparisonEngine.Evaluate(p,source,new(),Summons(),PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,CancellationToken.None,[model]).All(r=>r.Outcome==null));});
        test("Patch or source changes invalidate pet context keys",()=>{var p=Profile("MAG","WAR","CLR");var rows=Run(p);var first=rows[0].Scenario.InputKey;p.PetGoalWeights["DPS"]=new(){["AC"]=100};Check(Run(p)[0].Scenario.InputKey!=first);});
        test("Balanced goals keep two equipment dimensions",()=>{var p=Profile("MAG","WAR","CLR");var c=new Catalog{Items=[Item("blade",1)]};var b=new PetBuild{PetType="Air",Items=[Entry("blade",1,"Primary")]};var eq=PetEquipmentInference.Build(b,p.ActiveLoadout,c,false);var result=new LoadoutEvaluationSession(c,GuidedPetBuilds.Context(p.ActiveLoadout,b),true,PetRoleRatings.Weights(p,"DPS"),eq.Positions,eq.Positions,petGoal:"Balanced").CompareBuild(eq.Positions);Check(result.PetDefense!=null&&PetRoleRatings.Text(result).Contains("Damage")&&PetRoleRatings.Text(result).Contains("Defense"));Check(PetRoleRatings.Dominates(10,20,9,20));Check(!PetRoleRatings.Dominates(10,15,9,20));});
        test("Pet goals preserve old and custom weight dictionaries",()=>{var p=Profile("MAG");p.Weights["Pet DPS"]=new(){["AC"]=17};p.Weights["Pet custom"]=new(){["Mana"]=7};Check(PetRoleRatings.Weights(p,"DPS")["AC"]==17);Check(PetRoleRatings.Choices(p).Contains("Pet custom"));Check(PetRoleRatings.Weights(p,"Tank")["AC"]==3);Check(PetRoleRatings.Weights(p,"Balanced",true)["HP"]==.15);});
        test("Reassign respects two hands and preserves physical ranks",()=>{var p=Profile("MAG","WAR","CLR");var two=Item("two",10);two.TwoHanded=true;two.Slots=["PRIMARY"];two.Stats["Damage"]=50;var c=new Catalog{Items=[two,Item("one",1)]};var b=new PetBuild{PetType="Air",PetLevel=50,Items=[Entry("two",1,rank:3),Entry("one",2,rank:5)]};var before=JsonSerializer.Serialize(b);var plans=PetReassignment.Solve(b,p.ActiveLoadout,c,PetRoleRatings.Weights(p,"DPS"),PetRoleRatings.Weights(p,"Tank"),"DPS",CancellationToken.None);Check(plans.Count==1);var eq=PetEquipmentInference.Build(plans[0],p.ActiveLoadout,c,false);Check(eq.Positions.Single(x=>x.Slot=="Secondary").Item==null);Check(plans[0].Items[0].Rank==3&&plans[0].Items[1].Rank==5);Check(JsonSerializer.Serialize(b)==before);});
        test("Reassignment respects paired slots, capacity and incompatible bows",()=>{var p=Profile("MAG","WAR","CLR");var bow=Item("bow",500,["RANGE"]);bow.Display.Type="Bow";var c=new Catalog{Items=[Item("ring",3,["FINGER"]),bow]};var b=new PetBuild{PetType="Air",PetLevel=50,Items=[Entry("ring",1),Entry("ring",2),Entry("ring",3),Entry("bow",4),Entry("ring",20)]};var result=PetReassignment.Solve(b,p.ActiveLoadout,c,PetRoleRatings.Weights(p,"DPS"),PetRoleRatings.Weights(p,"Tank"),"Tank",CancellationToken.None).Single();var eq=PetEquipmentInference.Build(result,p.ActiveLoadout,c,false);Check(eq.Selections.Count==2);Check(result.Items.Where(i=>i.Slot!="Storage").All(i=>i.ItemKey=="ring"));});
        test("Reassignment retains non-dominated Balanced equipment choices",()=>{var p=Profile("MAG","WAR","CLR");var a=Item("damage",0,["PRIMARY"]);a.Stats["Damage"]=30;var d=Item("defense",100,["PRIMARY"]);d.Stats["Damage"]=1;var c=new Catalog{Items=[a,d]};var b=new PetBuild{PetType="Air",PetLevel=50,Items=[Entry("damage",1),Entry("defense",2)]};var plans=PetReassignment.Solve(b,p.ActiveLoadout,c,new(){["Ratio"]=100},new(){["AC"]=3},"Balanced",CancellationToken.None);Check(plans.Count==2);});
        test("Interrupted reassignment never publishes a partial optimum",()=>{var p=Profile("MAG");using var stop=new CancellationTokenSource();stop.Cancel();bool canceled=false;try{PetReassignment.Solve(new(),p.ActiveLoadout,new(),new(),new(),"DPS",stop.Token);}catch(OperationCanceledException){canceled=true;}Check(canceled);});
        test("Saving pet comparison creates isolated named theorycraft plan",()=>{var p=Profile("MAG","WAR","CLR");var before=JsonSerializer.Serialize(p);var row=Run(p)[0];var saved=PetComparisonEngine.SavePlan(row,"Test plan");Check(saved.IsTheorycraft&&saved.ComparisonScenario!=null&&saved.Id!=row.Plan.Id);Check(JsonSerializer.Serialize(p)==before);var copy=EquipmentPositions.Copy(saved);Check(copy.ComparisonScenario!.InputKey==row.Scenario.InputKey);});
        test("Pet plan Undo retains comparison assumptions",()=>{var b=new PetBuild{ComparisonScenario=new(){Goal="Tank"}};PetBuildEditing.Remember(b,"change");b.ComparisonScenario=new(){Goal="DPS"};Check(PetBuildEditing.Undo(b,out _)&&b.ComparisonScenario?.Goal=="Tank");});
        test("Historical sample rates use summed combat duration and never predict builds",()=>{var rows=PetComparisonEngine.History([new(){PetType="Air",Finished=true,PetDamage=100,Start=DateTime.Today,End=DateTime.Today.AddSeconds(10),DetailAvailable=false},new(){PetType="Air",Finished=true,PetDamage=300,Start=DateTime.Today,End=DateTime.Today.AddSeconds(30),DetailAvailable=false}]);Check(rows.Single().Dps==10&&rows[0].Melee==null&&rows[0].Conditions.Contains("not current-build prediction"));});
        test("Invalid encounter assumptions stay explicit",()=>{foreach(var value in new[]{-1,double.NaN,double.PositiveInfinity}){bool rejected=false;try{new PetEncounterAssumptions{IncomingDps=value}.Validate();}catch(ArgumentException){rejected=true;}Check(rejected);}new PetEncounterAssumptions().Validate();});
        PetBuffDefinition Buff(string id,double haste)=>new(){Id=id,Name=id,Classes=new(){["MAG"]=1},ParametersComplete=true,Effects=[new(1,11,haste,0,100,0)]};
        test("Pet buffs never add conflicting haste spells or duplicate identities",()=>{var a=Buff("burnout",40);var b=Buff("death",30);Check(PetBuffResolver.Pair(a,b).Excluded=="death");Check(PetBuffResolver.Pair(a,a).State=="Duplicate");var catalog=new PetBuffCatalog{Buffs=[a,b]};var rows=PetBuffResolver.Resolve(catalog,[new(){Id="burnout",Rank=0,Enabled=true},new(){Id="burnout",Rank=0,Enabled=true},new(){Id="death",Rank=0,Enabled=true}],Profile("MAG").ActiveLoadout,"Air",false);Check(rows.Count==2&&rows.Single(r=>r.Name=="death").State.StartsWith("Excluded"));});
        test("Complete buffs are excluded, never cherry-picked",()=>{var a=Buff("a",40);a.Effects.Add(new(2,4,5,0,100,0));var b=Buff("b",30);b.Effects.Add(new(2,4,10,0,100,0));var pair=PetBuffResolver.Pair(a,b);Check(pair.State=="Computed conflict"&&pair.Excluded==null);});
        test("Stacking commands use EQL limit slot and strict threshold",()=>{var a=Buff("block",0);a.Effects=[new(1,148,69,3,0,500)];var b=Buff("hp",0);b.Effects=[new(3,69,499,0,100,0)];Check(PetBuffResolver.Pair(a,b).Excluded=="hp");b.Effects=[new(3,69,500,0,100,0)];Check(PetBuffResolver.Pair(a,b).State=="Computed coexistence");});
        test("Unknown buff ranks, AA and external scope cannot imply confirmed bonuses",()=>{var a=Buff("bst",20);a.Classes=new(){["BST"]=1};var catalog=new PetBuffCatalog{Buffs=[a]};Check(PetBuffResolver.Resolve(catalog,[new(){Id="bst",Enabled=true}],Profile("MAG").ActiveLoadout,"Air",false).Single().State=="Excluded");a.Aa=true;Check(PetBuffResolver.Resolve(catalog,[new(){Id="bst",Enabled=true,External=true}],Profile("MAG").ActiveLoadout,"Air",true).Single().State=="Unverified AA");});
        test("Unsupported proc ids and scaled effects do not invent stacking winners",()=>{var a=Buff("a",5);var b=Buff("b",6);a.Effects=[new(1,85,123,0,100,0)];b.Effects=[new(1,85,999,0,100,0)];Check(PetBuffResolver.Pair(a,b).State=="Unresolved");a.Effects=[new(1,11,10,0,102,30)];b.Effects=[new(1,11,5,0,100,0)];Check(PetBuffResolver.Pair(a,b).State=="Unresolved");});
        string ClientRow(int fields=172){var f=Enumerable.Repeat("0",fields).ToArray();f[0]="42";f[1]="Synthetic Buff";f[12]="10";f[28]="1";f[30]="14";for(int n=36;n<52;n++)f[n]="255";f[48]="1";f[165]="0";f[167]=f[168]=f[169]="-1";f[^1]="1|11|30|0|100|0$2|4|10|0|100|0";return string.Join('^',f);}
        foreach(int width in new[]{171,172})test("Read-only pet spell adapter validates "+width+" fields",()=>{var c=PetClientSpellAdapter.Parse([ClientRow(width)],CancellationToken.None);var b=c.Buffs.Single(b=>b.Name=="Synthetic Buff");Check(b.Classes["MAG"]==1&&b.Effects.Count==2&&b.Effects[0].Spa==11&&b.Effects[1].Base==10);});
        test("Client format changes reject all numerical parameters",()=>{var c=PetClientSpellAdapter.Parse([ClientRow(),"1^Changed format"],CancellationToken.None);Check(c.Buffs.All(b=>!b.ParametersComplete)&&c.Status.Contains("rejected"));});
        test("Real known context can save ordinary plans without inventing a DPS model",()=>{var p=Profile("MAG","WAR","CLR");foreach(var s in Summons().Spells)p.PetComparison.Summons[s.Id]=new(){SpellId=s.Id,Rank=0,RankConfirmed=true,LearningConfirmed=true};var row=Run(p)[0];Check(row.Outcome==null&&!PetComparisonEngine.SavePlan(row,"Known summon").IsTheorycraft);});
        test("Pet comparison rows have distinct stable presentation identities",()=>{var p=Profile("MAG","WAR","CLR");var source=new PetBuild();var rows=Run(p,source);Check(rows.Select(r=>r.ToString()).Distinct().Count()==3);Check(Run(p,source).Select(r=>r.ToString()).SequenceEqual(rows.Select(r=>r.ToString())));});
        test("Lore-equipped copies cannot both be reassigned",()=>{var p=Profile("MAG","WAR","CLR");var ring=Item("lore",10,["FINGER"]);ring.Display.Flags=["LORE EQUIPPED"];var c=new Catalog{Items=[ring]};var b=new PetBuild{PetType="Air",PetLevel=50,Items=[Entry("lore",1),Entry("lore",2)]};var plan=PetReassignment.Solve(b,p.ActiveLoadout,c,new(){["AC"]=1},PetRoleRatings.Tank,"Tank",CancellationToken.None).Single();Check(PetEquipmentInference.Build(plan,p.ActiveLoadout,c,false).Selections.Count==1);});
        test("Recorded summon ranks above ten survive without enabling new out-of-range previews",()=>{var p=Profile("MAG","WAR","CLR");var b=new PetBuild{PetType="Air",SummonSpell="Air fixture",SummonClass="MAG",SummonRank=12};Check(Run(p,b).Single(r=>r.Pet=="Air").Plan.SummonRank==12);});
        test("Client parameter changes invalidate same-count buff catalog versions",()=>{var a=PetClientSpellAdapter.Parse([ClientRow()],CancellationToken.None);var b=PetClientSpellAdapter.Parse([ClientRow().Replace("1|11|30|","1|11|31|")],CancellationToken.None);Check(a.Version!=b.Version);});
        test("Custom retired Pet selections migrate without weight loss or collisions",()=>{var p=Profile("MAG");p.Weights["Pet damage"]=new(){["Mana"]=7};p.ActiveLoadout.PetPreset="Pet damage";PetRoleRatings.Apply(p);string name=p.ActiveLoadout.PetPreset;Check(name.StartsWith("Custom pet")&&PetRoleRatings.Weights(p,name)["Mana"]==7);PetRoleRatings.Apply(p);Check(p.ActiveLoadout.PetPreset==name&&p.Weights["Pet damage"]["Mana"]==7);});
    }
}
